def run(field_service, principal, ordered_fields):
    if not isinstance(ordered_fields, (list, tuple)):
        return {"error": "bad-fields"}

    # Process all fields maintaining order
    fields = {}
    tag_fields = []
    for field in ordered_fields:
        if not isinstance(field, (list, tuple)) or len(field) != 2:
            return {"error": "bad-fields"}
        name, value = field
        if not isinstance(name, str) or not isinstance(value, str):
            return {"error": "bad-fields"}

        # Special handling for control fields
        if name == "mode":
            if name in fields:
                return {"error": "bad-fields"}
            fields[name] = value
        elif name == "tag":
            tag_fields.append(value)
        else:
            return {"error": "bad-fields"}

    # Validate mode field
    mode = fields.get("mode", "read")
    if mode not in ("read", "write"):
        return {"error": "bad-fields"}

    # Check permissions
    if mode == "write" and principal != "writer":
        return {"error": "forbidden"}

    # Combine all tag values into tags list
    tags = tag_fields

    return field_service.dispatch({"mode": mode, "tags": tags})' app/service.py

